  packing('life.sport.gym','На гимнастику','sports','Дополнительная игровая ситуация вне школьного расписания: тренер по гимнастике попросил чистую форму, носки и воду. Резинка пригодится при длинных волосах; небольшое полотенце можно взять дополнительно.',
    ['sport-uniform','gym-socks','water'],['hair-tie','towel'],['helmet','swim-cap','reading-book'],
    {'sport-uniform':'Чистая форма указана тренером.','gym-socks':'Носки входят в список занятия.','water':'По условию воду нужно взять обязательно.','hair-tie':'Резинка может пригодиться для длинных волос.','towel':'Небольшое личное полотенце разрешено дополнительно.','helmet':'Сегодня гимнастика, а не катание.','swim-cap':'Бассейна сегодня нет.','reading-book':'Книга для чтения не указана в списке.'},
    ['Уточни список тренера.','Проверь чистую форму.','Приготовь воду.','Убери вещи в спортивную сумку.'],'Ориентируйся на список именно этого занятия.');
  packing('life.sport.bmx','Готовимся к BMX','sports','Дополнительная игровая ситуация в свободный день: встреча с тренером BMX. Приготовь для выхода шлем, защиту коленей, перчатки, закрытую спортивную обувь и воду. Обувь наденешь, защиту проверишь со взрослым, воду положишь в сумку. Велосипед проверяет взрослый.',
    ['helmet','knee-pads','gloves','sport-shoes','water'],['napkins'],['swimwear','flute','art-album'],
    {'helmet':'Шлем входит в обязательный список для катания.','knee-pads':'Защиту коленей попросил тренер.','gloves':'Перчатки указаны в списке.','sport-shoes':'По условию нужна закрытая спортивная обувь.','water':'Вода указана в списке.','napkins':'Салфетки можно взять дополнительно.','swimwear':'На BMX плавки не заменяют одежду для катания.','flute':'Музыкального занятия сейчас нет.','art-album':'Рисовать на этой тренировке не планируем.'},
    ['Сверь защиту со списком тренера.','Подготовь одежду и воду.','Попроси взрослого проверить велосипед и посадку защиты.','Собери свои вещи перед выходом.'],'Раздели список на защиту, одежду и воду.',{level:2,adultNote:'Исправность велосипеда и правильную посадку защиты проверяет взрослый.'});
  packing('life.sport.music-flute','На занятие музыкой','music','Дополнительная музыкальная мастерская, отдельно от школьной музыки в четверг. В этой истории педагог попросил блокфлейту, ноты, нотную тетрадь и карандаш в пенале. Это условие игры, а не обязательный список для каждого урока музыки.',
    ['flute','notes','music-notebook','pencil-case'],['water'],['drumsticks','guitar-pick','ball'],
    {'flute':'Сегодня занимаемся на блокфлейте.','notes':'Ноты указаны педагогом.','music-notebook':'В тетради будут записи занятия.','pencil-case':'По условию карандаш находится в пенале.','water':'Можно взять воду.','drumsticks':'Сегодня не занятие на барабанах.','guitar-pick':'Медиатор нужен для другого инструмента.','ball':'Спортивной тренировки сейчас нет.'},
    ['Посмотри задание педагога.','Приготовь свой инструмент.','Положи нужные ноты и тетрадь.','Проверь карандаш.'],'Выбирай принадлежности для инструмента из условия.');
  packing('life.sport.music-drums','Ритм-мастерская','music','Дополнительная ритм-мастерская в свободное время, отдельно от школьной музыки в четверг. По игровой памятке нужны барабанные палочки, ноты и карандаш в пенале. Нотную тетрадь можно взять по желанию.',
    ['drumsticks','notes','pencil-case'],['music-notebook','water'],['flute','guitar-pick','goggles'],
    {'drumsticks':'Палочки нужны для сегодняшнего инструмента.','notes':'На занятии будем читать ритм по нотам.','pencil-case':'Карандаш из пенала нужен для пометок.','music-notebook':'Тетрадь разрешена дополнительно.','water':'Воду можно взять.','flute':'Сегодня другой инструмент.','guitar-pick':'Сегодня другой инструмент.','goggles':'Занятия в воде сейчас нет.'},
    ['Уточни, на каком инструменте сегодня занятие.','Положи нужные принадлежности.','Найди ноты.','Проверь пенал.'],'Все музыкальные вещи не обязательно нужны на одном занятии.',{level:2});

  packing('life.trip.sunny-walk','Прогулка в солнечный день','outings','В выходной идём со взрослым в парк на час: день тёплый и солнечный. По памятке нужны вода и панама. Перекус и салфетки можно взять дополнительно. Всё должно поместиться в небольшой рюкзак; тёплая шапка в этот раз не требуется.',
    ['water','sunhat'],['lunchbox','napkins'],['warm-hat','large-robot','math-book'],
    {'water':'Вода входит в памятку прогулки.','sunhat':'Для солнечного дня в памятке указана панама.','lunchbox':'Подготовленный перекус разрешён дополнительно.','napkins':'Салфетки разрешены дополнительно.','warm-hat':'По условию день тёплый и солнечный.','large-robot':'По условию большая игрушка не помещается в маленький рюкзак.','math-book':'Школьных заданий на этой прогулке нет.'},
    ['Уточни погоду и длительность прогулки.','Приготовь воду и головной убор.','Проверь, удобно ли нести рюкзак.'],'Сначала обязательные вещи, потом небольшие дополнительные.');
  packing('life.trip.rain-walk','Прогулка после дождя','outings','В свободное от школы время идём со взрослым на короткую прогулку: возможен дождь. Приготовь дождевик, подходящие ботинки и салфетки; воду можно взять. Ботинки и дождевик наденешь, а салфетки положишь в сумку. Здесь выбираем всё для выхода, а не только содержимое сумки.',
    ['raincoat','boots','napkins'],['water'],['pool-slippers','swim-cap','art-album'],
    {'raincoat':'Дождевик указан в памятке прогулки.','boots':'По условию выбрана подходящая обувь для мокрой дорожки.','napkins':'Салфетки указаны в памятке.','water':'Воду можно взять дополнительно.','pool-slippers':'В условии прогулка по мокрой дорожке, не бассейн.','swim-cap':'Дождь не означает плавание.','art-album':'Рисование на прогулке не планируется.'},
    ['Посмотри погоду со взрослым.','Подготовь одежду и обувь.','Выбери удобную небольшую сумку.'],'Подумай о погоде и месте прогулки.');
  packing('life.trip.overnight','В гости с ночёвкой','outings','В выходной ночуем у бабушки. Кровать и полотенце там есть. Нужно взять пижаму, сменное бельё, чистые носки и зубную щётку. Небольшую книгу, мишку или обе небольшие вещи можно взять по желанию. Одной любимой вещи уже достаточно.',
    ['pajamas','underwear','clean-socks','toothbrush'],['storybook','teddy'],['towel','math-book','helmet'],
    {'pajamas':'Остаёмся на ночь: нужна одежда для сна.','underwear':'Чистое сменное бельё нужно по памятке.','clean-socks':'Носки на следующий день указаны в памятке.','toothbrush':'Личная щётка нужна для вечерней и утренней чистки.','storybook':'Небольшую книгу разрешено взять дополнительно.','teddy':'Небольшую любимую игрушку разрешено взять дополнительно.','towel':'По условию полотенце уже приготовлено у бабушки.','math-book':'Учебное задание на эту поездку не задано.','helmet':'Катание в этой поездке не планируется.'},
    ['Уточни, что уже есть в гостях.','Собери личные принадлежности.','Положи одежду на следующий день.','Выбери одну небольшую вещь для отдыха.'],'Не дублируй вещи, которые уже приготовлены на месте.',{level:2});
  packing('life.trip.library','В библиотеку','outings','В свободное от уроков время идём возвращать в библиотеку две конкретные книги: сказки и комикс. Воду можно взять. Одежда и обувь для пути уже надеты; дополнительную пару ботинок в сумку не кладём.',
    ['storybook','comics'],['water'],['ball','paints','boots'],
    {'storybook':'Эту книгу по условию нужно вернуть.','comics':'Комикс — вторая книга для возврата.','water':'Воду можно взять дополнительно.','ball':'Спортивной игры сейчас нет.','paints':'В библиотеке по условию не рисуем.','boots':'Обувь надевают по погоде; дополнительную пару в сумку не просили.'},
    ['Проверь, какие книги нужно вернуть.','Найди обе книги.','Сложи их аккуратно в сумку.'],'Вспомни цель похода: вернуть конкретные книги.');

  sequence('life.plan.bed','Заправляем постель','Утро. На постели остались игрушка и смятое покрывало. Сделаем спальное место аккуратным.',
    [['clear','Убрать игрушку на её место'],['sheet','Расправить простыню'],['blanket','Расправить одеяло'],['pillow','Положить подушку аккуратно']],
    [['clear','sheet'],['sheet','blanket'],['sheet','pillow']],
    ['Убери лишние вещи с постели.','Расправь простыню и одеяло.','Устрой подушку.','Проверь, удобно ли будет лечь вечером.'],'Сначала освободи постель. Одеяло и подушку после простыни можно устроить в разном порядке.');
  sequence('life.plan.desk','План для рабочего места','Нужно начать домашнее задание. На столе игрушки, крошки и разные книги.',
    [['choose','Посмотреть, какое задание будем делать'],['clear','Убрать лишние вещи'],['wipe','При необходимости протереть свободный стол'],['materials','Положить нужный учебник и тетрадь'],['tools','Приготовить ручку и карандаш'],['start','Удобно сесть и начать']],
    [['choose','materials'],['choose','tools'],['clear','wipe'],['wipe','materials'],['wipe','tools'],['materials','start'],['tools','start']],
    ['Выбери одно задание.','Освободи рабочее место.','Приготовь только нужные вещи.','Проверь, удобно ли сидеть.'],'Чтобы протереть стол, сначала его освобождают. Учебник и пенал можно приготовить в разном порядке.',{level:2});
  sequence('life.plan.school-evening','Спокойный школьный вечер','Вечером перед учебным днём соберём рюкзак заранее. Сначала выбери нужный день в расписании 2 А, потом проверь его уроки. Если готовимся ко вторнику или четвергу, отдельно проверим и сумку бассейна.',
    [['schedule','Посмотреть расписание на завтра'],['list','Назвать нужные учебники и тетради'],['pack','Положить нужные книги и тетради'],['pencil','Проверить пенал'],['check','Сверить собранное со списком'],['place','Поставить закрытый рюкзак на привычное место']],
    [['schedule','list'],['list','pack'],['pack','check'],['pencil','check'],['check','place']],
    ['Посмотри расписание.','Собери нужные вещи.','Сверься со списком.','Поставь рюкзак на привычное место.'],'Пенал можно проверить раньше или позже, но до общей проверки.');
  sequence('life.plan.pool-return','После бассейна','Во вторник или четверг бассейн «Золотая рыбка» закончился. Дома разберём сумку: мокрое отдельно от книг, полотенце в согласованное место, вещи для стирки взрослому. Поможем всему подготовиться к следующему занятию.',
    [['open','Открыть спортивную сумку'],['separate','Отделить мокрые вещи от сухих'],['hang','Повесить полотенце на согласованное место'],['wash','Передать вещи для стирки по договорённости'],['bag','Оставить пустую сумку просохнуть']],
    [['open','separate'],['separate','hang'],['separate','wash'],['separate','bag']],
    ['Разбери сумку после возвращения.','Отдели мокрое от сухого.','Повесь полотенце по договорённости.','Передай вещи для стирки взрослому.'],'Сначала открой сумку и найди мокрые вещи. После их можно разбирать в разном порядке.',{adultNote:'Стирку и подходящее место для сушки выбирают вместе со взрослым.'});
  sequence('life.plan.bedtime','Готовимся ко сну','Ужин закончился. Составь спокойный вечерний план.',
    [['tomorrow','Приготовить одежду на завтра'],['toys','Убрать несколько игрушек'],['teeth','Почистить зубы'],['pajamas','Надеть пижаму'],['story','Выбрать короткую историю для чтения'],['rest','Устроиться в постели']],
    [['tomorrow','rest'],['toys','rest'],['teeth','rest'],['pajamas','rest'],['story','rest']],
    ['Выбери удобный порядок вечерних дел.','Приготовь вещи на завтра.','Выполни привычные дела перед сном.','Устройся для отдыха.'],'Несколько вечерних дел можно менять местами. В постель устраиваемся после подготовки.',{level:1});
  sequence('life.plan.room','Уборка по маленьким шагам','В комнате много разных вещей. Сделаем понятный план, не пытаясь сделать всё сразу.',
    [['look','Посмотреть и выбрать небольшой участок'],['toys','Собрать игрушки на их места'],['books','Поставить книги на полку'],['clothes','Разделить чистую одежду и бельё для стирки'],['floor','Проверить, что проход свободен'],['finish','Посмотреть, что уже получилось']],
    [['look','toys'],['look','books'],['look','clothes'],['toys','floor'],['books','floor'],['clothes','floor'],['floor','finish']],
    ['Выбери маленький участок.','Убери один вид вещей.','Проверь проход.','Заметь, что стало удобнее.'],'После выбора участка книги, игрушки и одежду можно разбирать в любом порядке.',{level:2});
  sequence('life.plan.pet','Забота о котёнке','Поможем взрослому подготовить спокойное место для котёнка. Самого котёнка никуда не переносим.',
    [['ask','Спросить взрослого, чем можно помочь'],['place','Освободить согласованное место для лежанки'],['water','Помочь налить свежую воду по договорённости'],['toy','Положить подходящую игрушку в согласованное место'],['check','Вместе со взрослым проверить готовность'],['space','Оставить котёнку возможность спокойно отдохнуть']],
    [['ask','place'],['ask','water'],['ask','toy'],['place','check'],['water','check'],['toy','check'],['check','space']],
    ['Спроси взрослого о помощи.','Выполни одно согласованное дело.','Проверь результат вместе.','Дай питомцу спокойно отдохнуть.'],'Взрослый подскажет подходящие вещи и действия. Вода и игрушка готовятся после договорённости.',{level:2,adultNote:'Корм, лекарства и средства ухода выбирает взрослый. Животное не является предметом для сортировки.'});
  sequence('life.plan.trip-check','Перед выходом из дома','Вещи уже выбраны по памятке. Составь последнюю проверку перед выходом со взрослым.',
    [['list','Посмотреть памятку поездки'],['check','Сверить вещи с памяткой'],['close','Закрыть сумку'],['shoes','Надеть подходящую обувь'],['meet','Подойти к взрослому в условленное место']],
    [['list','check'],['check','close'],['close','meet'],['shoes','meet']],
    ['Сверься со своей памяткой.','Закрой сумку.','Оденься по погоде.','Встреться со взрослым в условленном месте.'],'Сумку закрывают после проверки. Обувь можно подготовить раньше или позже.');

  // New situations use new IDs. Existing real-plan checkbox positions above
