    'life.school.pe':[{id:'school',label:'Учебная часть',itemIds:['math-book','math-notebook','pencil-case','water']},{id:'sport',label:'Отдельно для физкультуры',itemIds:['sport-uniform','sport-shoes','shoe-bag']}],
