  quests.forEach(q=>{if(newMicroActions[q.id])q.microReal=newMicroActions[q.id];});


  // Every adventure has a genuinely small real action. It is deliberately
  // separate from the full checklist: one returned toy never means that the
  // entire room or the whole first checklist step has been completed.
  function prepareQuest(q){
    q.scene=q.scene||(q.mode==='pack'?'bag':q.category==='sorting'?'sorting':q.id.includes('.pet')?'pet':q.id.includes('.bed')?'bed':q.id.includes('.desk')?'desk':q.id.includes('pool-return')?'laundry':'room');
    q.firstMove=q.firstMove||(q.mode==='sequence'?'Выбери один шаг, с которого удобно начать.':q.mode==='pack'?'Прочитай цель. Выбери одну вещь, которая для неё нужна.':q.mode==='rule'?'Выбери правило. Потом посмотри на один предмет.':'Выбери одну вещь. Потом нажми на её место.');
    q.microReal=q.microReal||(q.category==='sorting'?'Возьми одну свою игрушку и назови её цвет, форму или размер.':q.mode==='pack'?'Посмотри памятку своего занятия и назови одну нужную вещь.':'Положи одну знакомую вещь на её привычное место.');
    if(q.id==='life.plan.bed')q.microReal='Убери одну игрушку с постели на её привычное место.';
    if(q.id==='life.plan.desk'||q.id==='life.places.desk')q.microReal='Убери со своего стола одну вещь, которая сейчас не нужна.';
    if(q.id==='life.plan.bedtime')q.microReal='Выбери одну вещь из одежды, которую приготовишь на завтра.';
    if(q.id==='life.plan.pet')q.microReal='Спроси взрослого, какое одно дело для питомца ты можешь сделать вместе с ним.';
    if(q.id==='life.plan.pool-return')q.microReal='Покажи взрослому мокрое полотенце и договорись, где его повесить.';
    if(q.id==='life.places.clothes')q.microReal='Найди одну вещь для стирки и положи её в корзину для белья.';
    if(q.id==='life.places.shopping')q.microReal='Спроси взрослого, куда можно убрать один принесённый продукт.';
    if(q.id==='life.plan.room')q.microReal='Выбери совсем маленький участок: например, один угол стола.';
    return q;
  }
  quests.forEach(prepareQuest);

  // Data checks are exposed for the independent engine/tests; no storage or
  // global progress is touched while loading this bank.
  function validate() {
    const errors=[],ids=new Set();
    function fail(q,message){errors.push((q&&q.id||'bank')+': '+message);}
    function mapOK(q,map){
      if(!map||typeof map!=='object'){fail(q,'missing accepted map');return;}
      q.itemIds.forEach(id=>{const allowed=map[id];if(!Array.isArray(allowed)||!allowed.length||allowed.some(z=>!q.zoneIds.includes(z)))fail(q,'invalid destinations for '+id);});
    }
    quests.forEach(q=>{
      if(ids.has(q.id))fail(q,'duplicate quest');ids.add(q.id);
      if(!['sort','pack','sequence','rule'].includes(q.mode))fail(q,'unknown mode');
      if(!q.title||!q.story||!q.instruction||!q.hint)fail(q,'missing child-facing text');
      if(!q.scene||!q.firstMove||!q.microReal)fail(q,'missing small-step teaching');
      if(q.realSteps.length<3||q.realSteps.length>5)fail(q,'real plan must have3-5steps');
      if(new Set(q.itemIds).size!==q.itemIds.length)fail(q,'duplicate item');
      q.itemIds.forEach(id=>{if(!items[id])fail(q,'unknown item '+id);});q.zoneIds.forEach(id=>{if(!zones[id])fail(q,'unknown zone '+id);});
      if(q.mode==='sort')mapOK(q,q.accepted);
      if(q.mode==='rule'){
        if(!Array.isArray(q.ruleChoices)||q.ruleChoices.length<2)fail(q,'missing rule choices');
        else q.ruleChoices.forEach(r=>mapOK(q,r.accepted));
      }
      if(q.mode==='pack'){
        const required=q.required||[],optional=q.optional||[],distractors=q.distractors||[],alternatives=(q.alternatives||[]).flatMap(g=>g.items||[]);
        const all=required.concat(optional,distractors,alternatives);
        if(new Set(all).size!==all.length)fail(q,'packing sets overlap');
        if(q.itemIds.length!==all.length||q.itemIds.some(id=>!all.includes(id)))fail(q,'packing partition incomplete');
        if(!required.length)fail(q,'no required objects');
        q.itemIds.forEach(id=>{if(!q.why[id])fail(q,'missing explanation '+id);});
        (q.alternatives||[]).forEach(g=>{if(!g.id||!g.items.length||g.min<1||g.max<g.min||g.max>g.items.length)fail(q,'invalid alternative group');});
      }
      if(q.mode==='sequence'){
        const steps=(q.steps||[]).map(s=>s.id),edges=Object.fromEntries(steps.map(id=>[id,[]]));
        if(steps.length<3||steps.length>7||new Set(steps).size!==steps.length)fail(q,'invalid steps');
        q.before.forEach(([a,b])=>{if(!steps.includes(a)||!steps.includes(b)||a===b)fail(q,'invalid sequence dependency');else edges[a].push(b);});
        const visited=new Set(),active=new Set();function visit(id){if(active.has(id)){fail(q,'cyclic sequence');return;}if(visited.has(id))return;active.add(id);edges[id].forEach(visit);active.delete(id);visited.add(id);}steps.forEach(visit);
      }
    });
    return {success:errors.length===0,errors,quests:quests.length,items:Object.keys(items).length,zones:Object.keys(zones).length,modes:quests.reduce((a,q)=>(a[q.mode]=(a[q.mode]||0)+1,a),{}),categories:quests.reduce((a,q)=>(a[q.category]=(a[q.category]||0)+1,a),{})};
  }
  function extend(payload) {
    payload=payload&&typeof payload==='object'?payload:{};
    const counts={items:0,zones:0,quests:0};
    const values=value=>Array.isArray(value)?value:value&&typeof value==='object'?Object.values(value):[];
    const safe=id=>typeof id==='string'&&/^[a-z][a-z0-9.-]{0,159}$/.test(id)&&!['constructor','prototype','__proto__'].includes(id);
    values(payload.items).forEach(value=>{if(!value||!safe(value.id)||items[value.id])return;item(value.id,value.label,value.icon,value.description,value);counts.items++;});
    values(payload.zones).forEach(value=>{if(!value||!safe(value.id)||zones[value.id])return;zone(value.id,value.label,value.icon,value.description);counts.zones++;});
    values(payload.quests).forEach(value=>{if(!value||!safe(value.id)||quests.some(q=>q.id===value.id))return;add(value);prepareQuest(quests[quests.length-1]);counts.quests++;});
    return counts;
  }
  root.LifeQuestData={version:1,items,zones,quests,validate,extend,prepareQuest,categories:{places:'Каждой вещи своё место',sorting:'Мастерская сортировки',school:'Собираемся в школу',sports:'Собираемся на тренировку',music:'Музыкальные занятия',outings:'Прогулки и поездки',planning:'Планируем реальные дела'}};
